#!/usr/bin/env node
/**
 * Cinejoy webOS - Milestone 5 Forensic Auditor Adversarial Stress Suite
 * Path: .agents/teamwork/auditor_m5/forensic_adversarial_m5.js
 * Author: auditor_m5
 */

const assert = require('assert');
const path = require('path');
const fs = require('fs');

let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
  }
}

// Load player code
const playerSource = fs.readFileSync(path.resolve(__dirname, '../../../app/js/player.js'), 'utf8');

function setupEnvironment() {
  const dom = new JSDOM(`<!DOCTYPE html><html><body>
    <div id="view-player" class="view active">
      <div id="player-container" class="player-container">
        <video id="main-video-player" class="player-video"></video>
        <div id="player-buffering" class="player-buffering-overlay" style="display: none;">
          <span id="player-buffering-text">Loading...</span>
        </div>
        <div id="player-error-dialog" class="player-modal-backdrop" style="display: none;">
          <h2 id="player-error-title">Error</h2>
          <p id="player-error-message">Message</p>
          <button id="player-error-retry-btn">Retry</button>
          <button id="player-error-switch-btn">Switch</button>
          <button id="player-error-exit-btn">Exit</button>
        </div>
        <div id="player-subtitles-modal" class="player-modal-backdrop" style="display: none;">
          <button id="player-subtitles-close-btn">Close</button>
          <div id="player-subtitles-list"></div>
        </div>
        <div id="player-server-modal" class="player-modal-backdrop" style="display: none;">
          <button id="player-server-close-btn">Close</button>
          <div id="player-server-list"></div>
        </div>
        <div id="player-feedback-toast" style="display: none;">
          <span id="player-feedback-text"></span>
        </div>
        <div id="player-osd" class="player-osd">
          <button id="player-back-btn">Back</button>
          <h2 id="osd-title">Title</h2>
          <span id="osd-meta-episode"></span>
          <span id="osd-badge-format"></span>
          <span id="osd-badge-server"></span>
          <span id="osd-current-time">00:00:00</span>
          <div id="osd-scrubber">
            <div id="osd-buffer-fill"></div>
            <div id="osd-progress-fill"></div>
            <div id="osd-scrub-thumb"></div>
          </div>
          <span id="osd-duration-time">00:00:00</span>
          <button id="osd-rewind-btn">Rewind</button>
          <button id="osd-play-btn" title="Play"><svg id="osd-play-icon"></svg></button>
          <button id="osd-forward-btn">Forward</button>
          <button id="osd-subtitles-btn"><span id="osd-subtitles-label">Subtitles</span></button>
          <button id="osd-server-btn"><span id="osd-server-label">Server</span></button>
        </div>
      </div>
    </div>
  </body></html>`, { url: 'http://127.0.0.1:8088' });

  const window = dom.window;
  const document = window.document;

  // Mock SpatialNav
  window.SpatialNav = {
    _trapped: false,
    _current: null,
    trap: function () { this._trapped = true; },
    untrap: function () { this._trapped = false; },
    isTrapped: function () { return this._trapped; },
    setFocus: function (el) { this._current = el; },
    getCurrentFocus: function () { return this._current; }
  };

  // Mock CinejoyApp
  window.CinejoyApp = {
    exited: false,
    exitPlayer: function () { this.exited = true; }
  };

  // Run player.js in context
  const scriptEl = document.createElement('script');
  scriptEl.textContent = playerSource;
  document.body.appendChild(scriptEl);

  return { window, document, PlayerController: window.PlayerController, PlayerOSDController: window.PlayerOSDController };
}

let passed = 0;
let failed = 0;

function runTest(name, fn) {
  try {
    fn();
    console.log(`  ✓ PASS: ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ FAIL: ${name} -> ${err.message}`);
    console.error(err.stack);
    failed++;
  }
}

async function runAsyncTest(name, fn) {
  try {
    await fn();
    console.log(`  ✓ PASS: ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ FAIL: ${name} -> ${err.message}`);
    console.error(err.stack);
    failed++;
  }
}

async function main() {
  console.log('Starting Forensic Auditor Adversarial Stress Battery on Milestone 5...');

  // Group 1: Math & String Formatting Stress
  console.log('\n--- Group 1: Time Formatting & Key Math Edge Cases ---');
  const { PlayerController, PlayerOSDController } = setupEnvironment();
  const formatTime = PlayerOSDController.formatTime;
  const getKey = PlayerController.getPlaybackStorageKey;

  runTest('formatTime handles zero and standard seconds', () => {
    assert.strictEqual(formatTime(0), '00:00:00');
    assert.strictEqual(formatTime(59), '00:00:59');
    assert.strictEqual(formatTime(60), '00:01:00');
    assert.strictEqual(formatTime(3600), '01:00:00');
    assert.strictEqual(formatTime(86399), '23:59:59');
    assert.strictEqual(formatTime(3661), '01:01:01');
  });

  runTest('formatTime gracefully handles adversarial inputs', () => {
    assert.strictEqual(formatTime(-1), '00:00:00');
    assert.strictEqual(formatTime(-99999), '00:00:00');
    assert.strictEqual(formatTime(NaN), '00:00:00');
    assert.strictEqual(formatTime(Infinity), '00:00:00');
    assert.strictEqual(formatTime(-Infinity), '00:00:00');
    assert.strictEqual(formatTime('60'), '00:00:00');
    assert.strictEqual(formatTime(null), '00:00:00');
    assert.strictEqual(formatTime(undefined), '00:00:00');
    assert.strictEqual(formatTime({}), '00:00:00');
  });

  runTest('getPlaybackStorageKey handles edge types and defaults', () => {
    assert.strictEqual(getKey(1234, 'movie'), 'cinejoy_playback_1234_movie');
    assert.strictEqual(getKey(1234, 'tv', 2, 5), 'cinejoy_playback_1234_tv_2_5');
    assert.strictEqual(getKey(1234, 'series', 0, 0), 'cinejoy_playback_1234_tv_1_1');
    assert.strictEqual(getKey(1234, 'series', null, undefined), 'cinejoy_playback_1234_tv_1_1');
    assert.strictEqual(getKey(1234, 'unknown_type'), 'cinejoy_playback_1234_movie');
  });

  // Group 2: Seek Clamping & Timeline Computation Stress
  console.log('\n--- Group 2: Seek Clamping & Timeline Computation Stress ---');
  runTest('Relative seek clamped to bounds [0, duration]', () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    const video = env.document.getElementById('main-video-player');
    video.currentTime = 50;
    video.duration = 100;
    pc.init({ videoElement: video });

    pc.seek(-100);
    assert.strictEqual(video.currentTime, 0);

    pc.seek(200);
    assert.strictEqual(video.currentTime, 100);

    pc.seek(-50);
    assert.strictEqual(video.currentTime, 50);
  });

  runTest('seekTo clamped to bounds [0, duration]', () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    const video = env.document.getElementById('main-video-player');
    video.currentTime = 50;
    video.duration = 100;
    pc.init({ videoElement: video });

    pc.seekTo(-20);
    assert.strictEqual(video.currentTime, 0);

    pc.seekTo(150);
    assert.strictEqual(video.currentTime, 100);

    pc.seekTo(75);
    assert.strictEqual(video.currentTime, 75);
  });

  runTest('updateTimeline with abnormal durations', () => {
    const env = setupEnvironment();
    const osd = env.PlayerOSDController;
    osd.init();

    // duration 0 -> 0%
    osd.updateTimeline(10, 0, 0);
    const prog = env.document.getElementById('osd-progress-fill');
    assert.strictEqual(prog.style.width, '0%');

    // negative duration
    osd.updateTimeline(10, -50, 0);
    assert.strictEqual(prog.style.width, '0%');

    // currentTime > duration -> clamped to 100%
    osd.updateTimeline(150, 100, 200);
    assert.strictEqual(prog.style.width, '100%');
  });

  // Group 3: 5-Stage Teardown & Idempotence
  console.log('\n--- Group 3: 5-Stage Teardown & Idempotence ---');
  runTest('Repeated destroy calls are strictly idempotent and clean', () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    const video = env.document.getElementById('main-video-player');
    pc.init({ videoElement: video });

    pc.destroy();
    assert.strictEqual(pc.state, 'IDLE');
    assert.strictEqual(pc.hls, null);
    assert(!video.hasAttribute('src'));

    // Consecutive destroy calls
    pc.destroy();
    pc.destroy();
    assert.strictEqual(pc.state, 'IDLE');
  });

  runTest('Operations after destroy do not crash', () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    pc.destroy();

    assert.doesNotThrow(() => pc.play());
    assert.doesNotThrow(() => pc.pause());
    assert.doesNotThrow(() => pc.togglePlayPause());
    assert.doesNotThrow(() => pc.seek(10));
    assert.doesNotThrow(() => pc.seekTo(50));
    assert.doesNotThrow(() => pc.savePlaybackPosition());
    assert.strictEqual(pc.isPlaying(), false);
    assert.strictEqual(pc.getCurrentTime(), 0);
  });

  // Group 4: Remote Key Dispatch & Focus Trapping
  console.log('\n--- Group 4: Remote Key Dispatch & Modal Focus Trapping ---');
  runTest('Back key (461) closes modal before exiting player view', () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    const osd = env.PlayerOSDController;
    const app = env.window.CinejoyApp;

    pc.init();
    osd.init();
    pc.state = 'PLAYING';

    osd.openServerModal();
    assert.strictEqual(env.document.getElementById('player-server-modal').style.display, 'flex');
    assert.strictEqual(env.window.SpatialNav.isTrapped(), true);

    // Press Back key
    env.window.dispatchEvent(new env.window.KeyboardEvent('keydown', { keyCode: 461, key: 'Back' }));
    assert.strictEqual(env.document.getElementById('player-server-modal').style.display, 'none');
    assert.strictEqual(env.window.SpatialNav.isTrapped(), false);
    assert.strictEqual(app.exited, false, 'App should NOT exit player yet; modal was closed');

    // Press Back key second time -> now exit player
    env.window.dispatchEvent(new env.window.KeyboardEvent('keydown', { keyCode: 461, key: 'Back' }));
    assert.strictEqual(app.exited, true, 'App exits player on second back key');
  });

  // Group 5: Stream Resolution Error Resilience
  console.log('\n--- Group 5: Stream Resolution Error Resilience ---');
  await runAsyncTest('loadStream rejects missing payload and transitions to ERROR', async () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    let caught = false;
    try {
      await pc.loadStream(null);
    } catch (err) {
      caught = true;
      assert(err.message.includes('RESOLVE_INVALID_ID'));
    }
    assert.strictEqual(caught, true);
    assert.strictEqual(pc.state, 'ERROR');
  });

  await runAsyncTest('loadStream rejects missing tmdbId and transitions to ERROR', async () => {
    const env = setupEnvironment();
    const pc = env.PlayerController;
    let caught = false;
    try {
      await pc.loadStream({ type: 'movie' });
    } catch (err) {
      caught = true;
      assert(err.message.includes('RESOLVE_INVALID_ID'));
    }
    assert.strictEqual(caught, true);
    assert.strictEqual(pc.state, 'ERROR');
  });

  console.log(`\n========================================================================`);
  console.log(`Auditor Forensic Stress Summary: ${passed} passed, ${failed} failed.`);
  console.log(`========================================================================\n`);

  if (failed > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

main().catch(err => {
  console.error('Fatal stress error:', err);
  process.exit(1);
});

